def solve(inp):
    a = np.array(inp)
    sep = next(j for j in range(a.shape[1]) if len(set(a[:,j]))==1)
    w = sep
    L = a[:,:w]; R = a[:,sep+1:]
    out = np.full((a.shape[0], w), 3)
    for s in (L, R):
        vals, counts = np.unique(s, return_counts=True)
        bg = vals[np.argmax(counts)]
        out[s!=bg] = 0
    return out.tolist()

print(np.array_equal(np.array(solve(inp.tolist())), out))
